+  onUpdateImage?: (imageObject: ImageObject) => void;
+}
+
+export function FloatingMultiImageActions({
+  onAddImage,
+  onUpdateImage
+}: FloatingMultiImageActionsProps = {}) {
+  const containerRef = useRef<HTMLDivElement>(null);
+  const t = useTranslations('Canvas');
+  const tMulti = useTranslations('Canvas.multiSelection');
+  const isReadOnly = useCanvasStore((state) => state.isReadOnly);
+  const stage = useCanvasStore((state) => state.stage);
+  const canvasPosition = useCanvasTransformStore((state) => state.position);
+  const canvasScale = useCanvasTransformStore((state) => state.scale);
+
+  const selection = useSelectionStore((state) => state.selection);
