+    useHistoryState();
+  const { bounds } = useMultiSelectBounds();
+  const { handleCopy, handlePaste } = useCopyPaste();
+  const { handleBatchDelete } = useCanvasDelete();
+
+  const [openFloatingPanel, setOpenFloatingPanel] = useState<'remix' | null>(
+    null
+  );
+
+  const selectedImages = useMemo(() => {
+    return selection.selected
+      .map((item) => canvasObjects.find((obj) => obj.id === item.id))
+      .filter((obj): obj is ImageObject => obj != null && isImageObject(obj));
+  }, [selection.selected, canvasObjects]);
+
+  const selectedObjects = useMemo(() => {
+    return selection.selected
+      .map((item) => canvasObjects.find((obj) => obj.id === item.id))
+      .filter(Boolean);
+  }, [selection.selected, canvasObjects]);
+
+  const allUnlocked = useMemo(
+    () => selectedObjects.every((obj) => !obj?.isLocked),
+    [selectedObjects]
+  );
+
+  const allVisible = useMemo(
+    () => selectedObjects.every((obj) => obj?.visible !== false),
+    [selectedObjects]
+  );
+
+  const { handleVisibilityChange } = useCanvasVisibility();
+  const { handleLockChange } = useCanvasLock();
+  const handleLock = useCallback(() => {
+    const ids = selection.selected.map((item) => item.id);
