+              <>
+                {openFloatingPanel === 'remix' && (
+                  <Tooltip>
+                    <TooltipTrigger asChild>
+                      <QuickActionButton
+                        variant="active"
+                        isActive
+                        label={t('quickActions.remix')}
+                      >
+                        <Sparkles size={16} />
+                      </QuickActionButton>
+                    </TooltipTrigger>
+                    <TooltipContent>
+                      <p>{t('quickActions.remix')}</p>
+                    </TooltipContent>
+                  </Tooltip>
+                )}
+                <Tooltip>
+                  <TooltipTrigger asChild>
