+                    <TooltipContent>
+                      <p>{t('quickActions.delete')}</p>
+                    </TooltipContent>
+                  </Tooltip>
+                )}
+                <Tooltip>
+                  <TooltipTrigger asChild>
+                    <QuickActionButton
+                      onClick={handleVisibilityChange}
+                      title={
+                        allVisible
+                          ? t('quickActions.hide')
+                          : t('quickActions.show')
+                      }
+                    >
+                      {allVisible ? (
+                        <EyeOff size={16} />
+                      ) : (
+                        <Eye size={16} />
