+                  </TooltipTrigger>
+                  <TooltipContent>
+                    <p>
+                      {allVisible
+                        ? t('quickActions.hide')
+                        : t('quickActions.show')}
+                    </p>
+                  </TooltipContent>
+                </Tooltip>
+                {allUnlocked && (
+                  <Tooltip>
+                    <TooltipTrigger asChild>
+                      <QuickActionButton
