+                        title={t('quickActions.lock')}
+                      >
+                        <Lock size={16} />
+                      </QuickActionButton>
+                    </TooltipTrigger>
+                    <TooltipContent>
+                      <p>{t('quickActions.lock')}</p>
+                    </TooltipContent>
+                  </Tooltip>
+                )}
+              </>
+            )}
+          </div>
+        </TooltipProvider>
+      </div>
+      <FloatingRemixContainer
+        open={openFloatingPanel === 'remix'}
+        onClose={() => setOpenFloatingPanel(null)}
+        selectedImages={selectedImages}
+        onAddImage={onAddImage ?? (() => {})}
+        onUpdateImage={onUpdateImage ?? handleUpdateImage}
+        onRemoveFromSelection={removeFromSelection}
+      />
+    </>
+  );
+}
