+++ b/hooks/use-multi-image-generate.ts
@@ -0,0 +1,235 @@
+'use client';
+
+import { useCallback, useState } from 'react';
+import { useTranslations } from 'next-intl';
+import { toast } from 'sonner';
+import { RequestStatus } from '@prisma/client';
+
+import type { ImageObject } from '@/components/canvas/types';
+import { useMultiSelectBounds } from '@/hooks/use-multi-select-bounds';
+import useIsBanned from '@/hooks/use-is-banned';
+import { useParallelGenerationStore } from '@/store/parallel-generation-store';
+import { getImageTarget, updateImage } from '@/utils/client/canvas/image';
+import { imageGenGemini, imageGenOpenAI } from '@/lib/client/image-generation';
+import { ImageGenerationMode } from '@/types/image-generation';
+import {
+  BASE_MODEL_GPT_IMAGE,
+  BASE_MODEL_NANO_BANANA_PRO
+} from '@/constants/image';
+import { IMAGE_GENERATION_COST } from '@/constants';
+import { compressImage } from '@/utils/image';
+import { spendToken } from '@/actions/token-balance';
+import { getImageDimensionsFromBase64 } from '@/utils/client/image';
+
+export interface UseMultiImageGenerateOptions {
+  selectedImages: ImageObject[];
+  onAddImage: (imageObject: ImageObject, parentId: string | null) => void;
+  onUpdateImage: (imageObject: ImageObject) => void;
+  onSuccess?: () => void;
+}
+
+export function useMultiImageGenerate({
+  selectedImages,
+  onAddImage,
+  onUpdateImage,
+  onSuccess
+}: UseMultiImageGenerateOptions) {
+  const [isGenerating, setIsGenerating] = useState(false);
+  const t = useTranslations('Canvas.multiSelection');
+  const tGenerate = useTranslations('Canvas.generateInfo');
+  const tError = useTranslations('errors');
+  const { isBanned, releaseAt } = useIsBanned();
+  const { center } = useMultiSelectBounds();
+  const canGenerate = useParallelGenerationStore((s) => s.canGenerate);
+  const concurrentLimit = useParallelGenerationStore((s) => s.concurrentLimit);
+
+  const handleGenerate = useCallback(
+    async (prompt: string, model: 'gemini' | 'gpt') => {
+      if (isBanned) {
+        toast.error(tError('userBanned', { releaseAt }));
+        return;
+      }
+
+      const multiGenPrompt = prompt.trim();
+      if (!multiGenPrompt) {
+        toast.error(t('batchGenerate.emptyPrompt'));
+        return;
+      }
+
+      if (selectedImages.length < 2) {
+        toast.error(t('batchGenerate.insufficientImages'));
+        return;
+      }
+
+      if (selectedImages.length > 16) {
+        toast.error(t('batchGenerate.tooManyImages'));
+        return;
+      }
+
+      if (!canGenerate()) {
+        toast.error(
+          tGenerate('concurrentLimitReached', { limit: concurrentLimit })
+        );
+        return;
+      }
+
+      if (!center) {
+        toast.error(t('batchGenerate.noBoundingBox'));
+        return;
+      }
+
+      const inputImages = selectedImages.map((img) => {
+        const currentImageId =
+          img.imageIds?.[img.currentIndex ?? 0] ?? img.imageId;
+        if (!currentImageId) {
+          throw new Error(
+            'Selected image must have a valid image ID from database'
+          );
+        }
+        return { id: currentImageId, source: 'canvas' as const };
+      });
+
+      const baseModel =
+        model === 'gpt' ? BASE_MODEL_GPT_IMAGE : BASE_MODEL_NANO_BANANA_PRO;
+      let generationId: string | null = null;
+
+      setIsGenerating(true);
+      try {
+        const metadata = await useParallelGenerationStore
+          .getState()
+          .startGeneration({
+            panelId: null,
+            prompt: multiGenPrompt,
+            width: 1024,
+            height: 1024,
+            position: center,
+            referenceImageObjectId: undefined,
+            baseModel,
+            source: 'user',
+            shouldGenerateNewImage: true,
+            cost: IMAGE_GENERATION_COST
+          });
+
+        generationId = metadata.id;
+        useParallelGenerationStore
+          .getState()
+          .updateGenerationStatus(generationId, 'IN_PROGRESS');
+
+        const result =
+          model === 'gpt'
+            ? await imageGenOpenAI({
+                type: ImageGenerationMode.multiImage,
+                prompt: multiGenPrompt,
+                inputImages
+              })
+            : await imageGenGemini({
+                type: ImageGenerationMode.multiImage,
+                prompt: multiGenPrompt,
+                inputImages,
+                modelName: BASE_MODEL_NANO_BANANA_PRO
+              });
+
+        if (result.requestStatus !== RequestStatus.COMPLETED) {
+          throw new Error(result.errorCode ?? 'Generation failed');
+        }
+
+        const MAX_SIZE = 10 * 1024 * 1024;
+        const compressedImages = await Promise.all(
+          result.images.map(async (imageBase64) => {
+            try {
+              const compressionResult = await compressImage(imageBase64, {
+                maxSize: MAX_SIZE,
+                initialQuality: 0.8,
+                minQuality: 0.4,
+                qualityStep: 0.1,
+                outputFormat: 'image/jpeg'
+              });
+              return compressionResult.dataUrl;
+            } catch {
+              return imageBase64;
+            }
+          })
+        );
+
+        await spendToken(IMAGE_GENERATION_COST, 'canvas-multi-image-generate')
+          .then(({ balance }) => {
+            const activeGenerations = Array.from(
+              useParallelGenerationStore.getState().activeGenerations.values()
+            );
+            const inFlightCost = activeGenerations
+              .filter(
+                (gen) =>
+                  gen.id !== generationId &&
+                  (gen.status === 'IN_QUEUE' || gen.status === 'IN_PROGRESS')
+              )
+              .reduce((total, gen) => total + gen.cost, 0);
+            console.log('Tokens charged for multi-image generation', {
+              cost: IMAGE_GENERATION_COST,
+              databaseBalance: balance,
+              inFlightCost
+            });
+          })
+          .catch((error) => {
+            console.error('Failed to spend token after generation', error);
+          });
+
+        const { width, height } = await getImageDimensionsFromBase64(
+          compressedImages[0]
+        );
+
+        const storedMetadata = useParallelGenerationStore
+          .getState()
+          .activeGenerations.get(generationId);
+        const indicatorPosition = storedMetadata?.indicatorPosition ?? center;
+
+        updateImage({
+          src: compressedImages,
+          width,
+          height,
+          imageGenerationId: result.id,
+          target: getImageTarget(null),
+          baseModel,
+          userPrompt: multiGenPrompt,
+          onAddImage,
+          onUpdateImage,
+          indicatorPosition
+        });
+
+        useParallelGenerationStore.getState().completeGeneration(generationId);
+        toast.success(t('batchGenerate.success'));
+        onSuccess?.();
+      } catch (error) {
+        console.error('Multi-image generation failed:', error);
+        if (generationId) {
+          useParallelGenerationStore
+            .getState()
+            .failGeneration(
+              generationId,
+              error instanceof Error ? error.message : String(error)
+            );
+        }
+        toast.error(
+          error instanceof Error ? error.message : t('batchGenerate.error')
+        );
+      } finally {
+        setIsGenerating(false);
+      }
+    },
+    [
+      isBanned,
+      releaseAt,
+      tError,
+      t,
+      tGenerate,
+      selectedImages,
+      canGenerate,
+      concurrentLimit,
+      center,
+      onAddImage,
+      onUpdateImage,
+      onSuccess
+    ]
+  );
+
+  return { handleGenerate, isGenerating };
+}
