+  }, [selection.selected, canvasObjects]);
+
+  const selectedObjects = useMemo(() => {
+    return selection.selected
+      .map((item) => canvasObjects.find((obj) => obj.id === item.id))
+      .filter(Boolean);
+  }, [selection.selected, canvasObjects]);
+
+  const allUnlocked = useMemo(
+    () => selectedObjects.every((obj) => !obj?.isLocked),
+    [selectedObjects]
+  );
+
+  const allVisible = useMemo(
+    () => selectedObjects.every((obj) => obj?.visible !== false),
+    [selectedObjects]
+  );
