+    // Anchor to top-center of selection group.
+    // Toolbar uses -translate-x-1/2 so left must be the center x.
+    const topCenter = {
+      x: bounds.x + bounds.width / 2,
+      y: bounds.y
+    };
+    const screenPoint = canvasToScreenCoordinates(topCenter, stage);
+    const rect = container.getBoundingClientRect();
