@@ -0,0 +1,102 @@
+'use client';
+
+import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
+
+import type { ImageObject } from '@/components/canvas/types';
+import { useMultiSelectBounds } from '@/hooks/use-multi-select-bounds';
+import { useMultiImageGenerate } from '@/hooks/use-multi-image-generate';
+import { useCanvasStore } from '@/store/canvas-store';
+import { useCanvasTransformStore } from '@/store/canvas-transform-store';
+import { canvasToScreenCoordinates } from '@/utils/canvas/coordinate-transform';
+
+import type { RemixSelectedImagePreview } from './FloatingTextarea';
+import { FloatingTextarea } from './FloatingTextarea';
+
+const TEXTAREA_WIDTH = 480;
+const GAP_BELOW_GROUP = 8;
+
+export interface FloatingRemixContainerProps {
+  open: boolean;
+  onClose: () => void;
+  selectedImages: ImageObject[];
+  onAddImage: (imageObject: ImageObject, parentId: string | null) => void;
+  onUpdateImage: (imageObject: ImageObject) => void;
+  /** Remove an image from the current selection (deselect) */
+  onRemoveFromSelection?: (imageId: string) => void;
+}
+
+export function FloatingRemixContainer({
+  open,
+  onClose,
+  selectedImages,
+  onAddImage,
+  onUpdateImage,
+  onRemoveFromSelection
+}: FloatingRemixContainerProps) {
+  const containerRef = useRef<HTMLDivElement>(null);
+  const stage = useCanvasStore((state) => state.stage);
+  const { bounds } = useMultiSelectBounds();
+  const position = useCanvasTransformStore((state) => state.position);
+  const scale = useCanvasTransformStore((state) => state.scale);
+  const [prompt, setPrompt] = useState('');
+  const [model, setModel] = useState<'gemini' | 'gpt'>('gemini');
+
+  const { handleGenerate, isGenerating } = useMultiImageGenerate({
+    selectedImages,
+    onAddImage,
+    onUpdateImage,
+    onSuccess: onClose
+  });
+
+  const selectedImagesPreview = useMemo((): RemixSelectedImagePreview[] => {
+    return selectedImages.map((img) => {
+      const src =
+        typeof img.src === 'string'
+          ? img.src
+          : img.src?.[img.currentIndex ?? 0] ?? '';
+      return { id: img.id, src };
+    });
+  }, [selectedImages]);
+
+  const updatePosition = useCallback(() => {
+    const container = containerRef.current;
+    if (!container || !bounds || !stage || !open) return;
+
+    // Anchor to bottom-center of selection group; textarea sits just below.
+    // FloatingTextarea uses -translate-x-1/2 so left must be the center x (not left edge).
+    const bottomCenter = {
+      x: bounds.x + bounds.width / 2,
+      y: bounds.y + bounds.height
+    };
+    const screenPoint = canvasToScreenCoordinates(bottomCenter, stage);
+    container.style.left = `${screenPoint.x}px`;
+    container.style.top = `${screenPoint.y + GAP_BELOW_GROUP}px`;
+  }, [bounds, stage, open]);
+
+  useEffect(() => {
+    updatePosition();
+  }, [updatePosition, bounds, stage, open, position.x, position.y, scale]);
+
+  const handleSubmit = useCallback(() => {
+    handleGenerate(prompt, model);
+  }, [handleGenerate, prompt, model]);
+
+  const visible = open && selectedImages.length >= 2;
+
+  return (
+    <FloatingTextarea
+      ref={containerRef}
+      variant="remix"
+      value={prompt}
+      onChange={setPrompt}
+      onSubmit={handleSubmit}
+      visible={visible}
+      width={TEXTAREA_WIDTH}
+      isGenerating={isGenerating}
+      selectedRemixModel={model}
+      onRemixModelChange={setModel}
+      selectedImages={selectedImagesPreview}
+      onRemoveRemixImage={onRemoveFromSelection}
+    />
+  );
+}
