+'use client';
+
+import { useCallback, useMemo } from 'react';
+import { toast } from 'sonner';
+import { useTranslations } from 'next-intl';
+
+import { useSelectionStore } from '@/store/selection-store';
+import { useHistoryState } from '@/hooks/use-history-state';
+import useSaveCanvas from '@/hooks/use-canvas-save';
+
+/**
+ * 統一管理 Canvas 物件「可見/隱藏」切換。
+ * 從 selection store 與 history state 讀取目前選取與物件，供 FloatingQuickActions / FloatingMultiImageActions 共用。
+ */
+export function useCanvasVisibility() {
+  const t = useTranslations('Canvas');
+  const selection = useSelectionStore((state) => state.selection);
+  const { canvasObjects, updateTempCanvasObjects, commitTempCanvasObjects } =
+    useHistoryState();
+  const { debouncedSave } = useSaveCanvas();
+
+  const selectedIds = useMemo(
+    () => selection.selected.map((item) => item.id),
+    [selection.selected]
+  );
+
+  const allCurrentlyVisible = useMemo(() => {
+    const selected = selection.selected
+      .map((item) => canvasObjects.find((obj) => obj.id === item.id))
+      .filter(Boolean);
+    return selected.every((obj) => obj?.visible !== false);
+  }, [selection.selected, canvasObjects]);
+
+  const handleVisibilityChange = useCallback(() => {
+    if (!selectedIds.length) return;
+    const newVisibility = !allCurrentlyVisible;
+    updateTempCanvasObjects((prev) =>
+      prev.map((obj) =>
+        selectedIds.includes(obj.id) ? { ...obj, visible: newVisibility } : obj
+      )
+    );
+    commitTempCanvasObjects({
+      type: 'Changed Visibility',
+      objectId: selectedIds[0]
+    });
+    debouncedSave();
+    toast.success(
+      newVisibility ? t('quickActions.showSuccess') : t('quickActions.hideSuccess')
+    );
+  }, [
+    selectedIds,
+    allCurrentlyVisible,
+    updateTempCanvasObjects,
+    commitTempCanvasObjects,
+    debouncedSave,
+    t
+  ]);
+
+  return { handleVisibilityChange };
+}
